import {
  Component,
  h,
  Prop,
  Element,
  Event,
  EventEmitter,
  State,
  Host,
  ComponentInterface,
  Watch,
} from '@stencil/core';
import classnames from 'classnames';
import { ValueFieldInputSize, ValueField, ValueFieldGroup, ValueFieldFreeSoloConfig } from './types';
import { Slot, Slots, Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { Status } from '@src/shared/base-props';
import { KsIconFilledClose } from '@fe-infra/keystone-icons-stencil';

const prefix = 'value-field';
/**
 * @slot prefix - Slot for prefix content.
 * @slot suffix - Slot for suffix content.
 * @slot closeIcon - Slot for the close icon.
 * @part base - The base container of the component.
 * @part prefix - The prefix container.
 * @part suffix - The suffix container.
 * @part suffixIcon
 */
@Component({
  tag: 'ks-value-field',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsValueField implements ComponentInterface {
  @Element() el!: HTMLKsValueFieldElement;

  private suffixEl?: HTMLElement;

  /** private type */
  @Prop() type?: 'tagged' | 'grouped' | 'texted';
  /** Whether the fields presenter is disabled. If `true`, interaction is not allowed. */
  @Prop() disabled?: boolean;
  /** The validation status of the input field. Can be `'success'`, `'warning'`, `'error'`, or `'default'`. */
  @Prop() status: Status = 'default';

  /** The placeholder text to display when no items are selected. */
  @Prop() placeholder?: string;

  /** The default value of the fields presenter, an array of objects representing selected items. */
  @Prop() defaultValue?: ValueField[];
  /** The current value of the fields presenter, an array of objects representing selected items. */
  @Prop() @Vue2ValueFix() value?: ValueField[] | ValueFieldGroup[];

  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: ValueField[] | ValueFieldGroup[];

  /** The size of the input field. */
  @Prop() size: ValueFieldInputSize = 'lg';

  /** Whether to display a clear button to remove all selected items. */
  @Prop() clearable?: boolean;

  /** Whether the value field element has focus. */
  @Prop() focusElement?: boolean;

  /** The height of the value field. */
  @Prop() valueFieldHeight?: string | number | { min?: string | number; max?: string | number };

  /** Whether to collapse multiple selected items into a summary view. Default: `true`. */
  @Prop() tagsEllipsis = true;

  /** Only works when `multiple` is set to `true` or `grouped`. Determines whether tags should display close buttons. */
  @Prop() closeable = true;

  /** Emitted when the selected items change. The event detail contains an array of the new selected items. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<ValueField[] | ValueFieldGroup[]>;

  /** Emitted when the field is cleared. The event does not contain any detail. */
  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;

  /** Emitted when a key is pressed in the input field. */
  @Event({ bubbles: false, composed: false }) ksInputKeyDown!: EventEmitter<KeyboardEvent>;

  /** Whether to enable input. */
  @Prop() enableInput?: boolean;

  /** The value of the input field. */
  @Prop() inputValue?: string;

  /** The default value of the input field. */
  @Prop() inputDefaultValue?: string;

  /** Emitted when the input value is changed. */
  @Event({ bubbles: false, composed: false }) ksInputChange!: EventEmitter<string>;
  @Uncontrollable('inputValue', 'inputDefaultValue', 'ksInputChange') @State() internalInputValueState?: string;

  /** whether auto clear the input value (when value field changes). */
  @Prop() autoClearInputValue = true;

  /** Configuration for free input mode, allowing input of any value not in the options list. */
  @Prop() freeSolo?: ValueFieldFreeSoloConfig;

  /** Whether the value field element is auto-focused. */
  @Prop() autoFocus?: boolean;

  /** The component that display in the prefix area */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  @State() _suffixOffset?: number;

  componentDidRender(): void {
    if (this.suffixEl) {
      const style = getComputedStyle(this.suffixEl);
      const nextSuffixOffset =
        (this.suffixEl.clientWidth || 0) +
        parseInt(style.marginLeft) +
        parseInt(style.marginRight) +
        // pass inline end offset to tagged view 4px padding
        // eslint-disable-next-line @typescript-eslint/no-magic-numbers
        4;
      if (this._suffixOffset !== nextSuffixOffset) {
        this._suffixOffset = nextSuffixOffset;
      }
    }
  }

  @Watch('internalValueState')
  handleInternalValueChange(newValue: ValueField[] | ValueFieldGroup[], oldValue: ValueField[] | ValueFieldGroup[]) {
    if (this.autoClearInputValue) {
      // diff newValue and oldValue, compare the values inside the array.
      if (!oldValue || newValue.length !== oldValue.length) {
        this.internalInputValueState = '';
      } else {
        const newValues = newValue
          .flatMap((item: ValueFieldGroup | ValueField) =>
            (item as ValueFieldGroup).children ? (item as ValueFieldGroup).children : item,
          )
          .map((item) => item.value);
        const oldValues = oldValue
          .flatMap((item: ValueFieldGroup | ValueField) =>
            (item as ValueFieldGroup).children ? (item as ValueFieldGroup).children : item,
          )
          .map((item) => item.value);
        if (newValues.some((item) => !oldValues.includes(item))) {
          this.internalInputValueState = '';
        }
      }
    }
  }

  render() {
    const className = classnames(`${prefix}`, `${prefix}--${this.size}`, {
      [`${prefix}--collapse`]: this.tagsEllipsis,
      [`${prefix}--scroll`]: !this.tagsEllipsis,
      [`${prefix}--focus`]: this.focusElement,
      [`${prefix}--disabled`]: this.disabled,
      [`${prefix}--${this.status}`]: this.status,
      [`${prefix}--${this.status}--focus`]: this.focusElement,
    });
    return (
      <Host class="KsValueField">
        <div class={className} part="base">
          {this.prefixSlot && (
            <span class={`${prefix}__prefix`} part="prefix">
              <slot name="prefix"></slot>
            </span>
          )}
          <div class={`${prefix}__container`}>
            <slot>
              {this.type === 'tagged' && (
                <ks-tagged-value-field
                  value={this.internalValueState as ValueField[]}
                  disabled={this.disabled}
                  tagsEllipsis={this.tagsEllipsis}
                  closeable={this.closeable}
                  valueFieldHeight={this.valueFieldHeight}
                  suffixOffset={this._suffixOffset}
                  focusElement={this.focusElement}
                  enableInput={this.enableInput}
                  placeholder={this.placeholder}
                  inputValue={this.internalInputValueState}
                  onKsInputChange={({ detail: value }) => {
                    this.internalInputValueState = value;
                  }}
                  onKsInputKeyDown={({ detail: event }) => {
                    this.ksInputKeyDown.emit(event);
                    if (!event.isComposing && !event.defaultPrevented) {
                      if (event.code === 'Enter' && this.internalInputValueState) {
                        event.preventDefault();

                        if (this.freeSolo) {
                          if (this.internalValueState?.find((item) => item.value === this.internalInputValueState)) {
                            this.internalValueState = this.internalValueState.filter(
                              (item) => item.value !== this.internalInputValueState,
                            );
                          } else {
                            if (typeof this.freeSolo === 'object') {
                              this.internalValueState = [
                                ...(this.internalValueState || []),
                                this.freeSolo.valueFieldFromInput(this.internalInputValueState),
                              ];
                            } else {
                              this.internalValueState = [
                                ...(this.internalValueState || []),
                                {
                                  value: this.internalInputValueState,
                                  label: this.internalInputValueState,
                                },
                              ];
                            }
                          }
                        }
                      } else if (event.code === 'Backspace' && !this.internalInputValueState) {
                        this.internalValueState = this.internalValueState?.slice(0, -1);
                      }
                    }
                  }}
                  onKsTagClose={({ detail: value }) => {
                    this.internalValueState = this.internalValueState?.filter((item) => item.value !== value);
                  }}
                  autoFocus={this.autoFocus}
                  data-testid="ks-value-field-index-crGNfo"
                />
              )}

              {this.type === 'grouped' && (
                <ks-grouped-value-field
                  value={this.internalValueState as ValueFieldGroup[]}
                  size={this.size}
                  disabled={this.disabled}
                  valueFieldHeight={this.valueFieldHeight}
                  suffixOffset={this._suffixOffset}
                  placeholder={this.placeholder}
                  closeable={this.closeable}
                  onKsTagClose={({ detail: { groupValue, value } }) => {
                    this.internalValueState = (this.internalValueState as ValueFieldGroup[])
                      ?.map((groupItem: ValueFieldGroup) => {
                        if (groupItem.value === groupValue) {
                          return {
                            ...groupItem,
                            children: groupItem.children?.filter((child) => child.value !== value),
                          };
                        } else {
                          return groupItem;
                        }
                      })
                      .filter((groupItem) => groupItem.children.length);
                  }}
                  autoFocus={this.autoFocus}
                  data-testid="ks-value-field-index-7TMVU2"
                />
              )}

              {this.type === 'texted' && (
                <ks-texted-value-field
                  size={this.size}
                  value={this.internalValueState}
                  valueFieldHeight={this.valueFieldHeight}
                  disabled={this.disabled}
                  suffixOffset={this._suffixOffset}
                  focusElement={this.focusElement}
                  enableInput={this.enableInput}
                  placeholder={this.placeholder}
                  inputValue={this.internalInputValueState}
                  onKsInputChange={({ detail: value }) => {
                    this.internalInputValueState = value;
                  }}
                  autoFocus={this.autoFocus}
                  data-testid="ks-value-field-index-2w1T59"
                  exportparts="mirror: inputMirror"
                />
              )}
            </slot>
          </div>

          <div part="suffix" class={`${prefix}__suffix`} ref={(el) => (this.suffixEl = el)}>
            {(this.clearable && this.value?.length && (
              <div
                part="suffixIcon"
                onClick={(event) => {
                  event.stopPropagation();
                  this.ksClear.emit();
                  this.internalValueState = [];
                }}
                class={`${prefix}__clear`}
                data-testid="ks-value-field-index-fdHRbt"
              >
                {this.focusElement && (
                  <slot name="closeIcon">
                    <KsIconFilledClose size="16" />
                  </slot>
                )}
              </div>
            )) ||
              null}
            <slot name="suffix"></slot>
          </div>
        </div>
      </Host>
    );
  }
}
